import{z}from"zod";const schema=z.object({NEXT_PUBLIC_APP_URL:z.string().url(),NEXT_PUBLIC_SUPABASE_URL:z.string().url(),NEXT_PUBLIC_SUPABASE_ANON_KEY:z.string().min(20),SUPABASE_SERVICE_ROLE_KEY:z.string().min(20).optional()});let cached:z.infer<typeof schema>|null=null;export function serverEnv(){if(cached)return cached;const parsed=schema.safeParse(process.env);if(!parsed.success)throw new Error("ENV_CONFIGURATION_INVALID");cached=parsed.data;return cached}